const fileName = $json.name || $json.fileName || $binary.coverFile?.fileName || '';
const mimeType = $binary.coverFile?.mimeType || $json.mimeType || '';

const allowedExtensionMatch = fileName.match(/\.(pdf|png)$/i);
const isbnMatch = fileName.match(/(\d{10,13})/);

const defaultISBN = "1234567890123";

const isSupportedFile = Boolean(allowedExtensionMatch);
const extension = allowedExtensionMatch ? allowedExtensionMatch[1].toLowerCase() : "";

const isbn = isbnMatch ? isbnMatch[1] : defaultISBN;

return [
  {
    json: {
      isValidFileName: isSupportedFile,
      isbn,
      extension,
      fileName,
      originalFileName: fileName,
      mimeType,
      googleDriveFileId: $json.id,
      uploadedAt: new Date().toISOString(),
      fileNameWarning: isbnMatch
        ? ""
        : "ISBN not found in file name. Default demo ISBN used for author mapping."
    },
    binary: $binary,
  },
];

