return items.map((item) => {
  const data = { ...item.json };

  const issueText = String(data.issueDetailsText || "").toLowerCase();
  const correctionText = String(data.correctionInstructions || "").toLowerCase();

  const hasNoCorrection =
    correctionText.includes("no correction required") ||
    correctionText.includes("no corrections required") ||
    correctionText.includes("no correction is required");

  const hasFailMarker = issueText.includes("❌");

  const hasPositiveChecks = issueText.includes("✅");

  const textSaysGood =
    issueText.includes("does not overlap") ||
    issueText.includes("do not enter") ||
    issueText.includes("safe margins are respected") ||
    issueText.includes("text is legible") ||
    issueText.includes("does not look pixelated") ||
    issueText.includes("award text is present") ||
    issueText.includes("expected award text");

  const clearRealProblem =
    hasFailMarker ||
    issueText.includes("overlap detected") ||
    issueText.includes("author name overlaps") ||
    issueText.includes("text overlaps with") ||
    issueText.includes("safe margin violation") ||
    issueText.includes("pixelated or blurry issue") ||
    issueText.includes("low resolution issue");

  // Main override:
  // If AI says all checks are positive and no correction required,
  // force PASS even if backend marked Low Resolution due to cropped demo image size.
  if (hasNoCorrection && hasPositiveChecks && textSaysGood && !clearRealProblem) {
    data.status = "PASS";
    data.issueType = "None";
    data.severity = "Low";
    data.confidenceScore = Math.max(Number(data.confidenceScore || 0), 94);
    data.correctionInstructions =
      "No correction required. The cover follows the validation rules.";
  }

  // Safety cleanup for Airtable select options
  if (!["PASS", "REVIEW NEEDED"].includes(data.status)) {
    data.status = "REVIEW NEEDED";
  }

  if (!["Low", "Medium", "High", "Critical"].includes(data.severity)) {
    data.severity = data.status === "PASS" ? "Low" : "High";
  }

  return {
    json: data,
    binary: item.binary,
  };
});

